// Library theory for: list.append, list.pop, str.index, str slicing
// ---------------------------------------------------------------

// list.append: "Append object to the end of the list."
function ListAppend<T>(xs: seq<T>, x: T): seq<T>
{
  xs + [x]
}

// list.pop: "Remove and return item at index (default last).
//            Raises IndexError if list is empty or index is out of range."
// Models the default-argument form pop(); the precondition encodes the IndexError case.
// Returns (list after removal, removed item).
function ListPop<T>(xs: seq<T>): (seq<T>, T)
  requires |xs| > 0
{
  (xs[..|xs| - 1], xs[|xs| - 1])
}

// Helper for str.index: lowest index j >= i such that sub occurs in s at position j,
// or -1 if there is no such index.
function StrFindFrom(s: string, sub: string, i: nat): int
  requires i <= |s|
  decreases |s| - i
{
  if i + |sub| > |s| then -1
  else if s[i..i + |sub|] == sub then i
  else if i + 1 > |s| then -1
  else StrFindFrom(s, sub, i + 1)
}

// "substring sub is found" in S
predicate StrContains(s: string, sub: string)
{
  StrFindFrom(s, sub, 0) >= 0
}

// str.index: "Return the lowest index in S where substring sub is found ...
//             Raises ValueError when the substring is not found."
// Models the form without start/end; the precondition encodes the ValueError case.
function StrIndex(s: string, sub: string): int
  requires StrContains(s, sub)
{
  StrFindFrom(s, sub, 0)
}

// Python slice bound normalisation (slice notation): a negative index i means len+i;
// the result is then clamped into [0, len].
function PySliceIndex(i: int, len: nat): nat
{
  if i < 0 then (if len + i < 0 then 0 else len + i)
  else if i > len then len
  else i
}

// Slice s[:k] (prefix up to, not including, normalised k)
function StrSliceTo(s: string, k: int): string
{
  s[..PySliceIndex(k, |s|)]
}

// Slice s[k:] (suffix starting at normalised k)
function StrSliceFrom(s: string, k: int): string
{
  s[PySliceIndex(k, |s|)..]
}
