```dafny
// Library theory for: str.split() (sep=None), sorted, str.join, dict.items

// str.split: "When set to None (the default value), will split on any
// whitespace character (including \n \r \t \f and spaces) and will discard
// empty strings from the result."
// The whitespace set is Python's str.isspace set, which the doc's "including"
// list covers in part. Code points: 9-13, 28-32, 0x85, 0xA0, 0x1680,
// 0x2000-0x200A, 0x2028, 0x2029, 0x202F, 0x205F, 0x3000.
predicate IsPyWhitespace(c: char)
{
  var n := c as int;
  (9 <= n && n <= 13) || (28 <= n && n <= 32)
  || n == 0x85 || n == 0xA0 || n == 0x1680
  || (0x2000 <= n && n <= 0x200A)
  || n == 0x2028 || n == 0x2029 || n == 0x202F || n == 0x205F || n == 0x3000
}

// Helper for str.split(): scan s front to back, cur is the token being built.
// "Splitting starts at the front of the string and works to the end."
// "... will discard empty strings from the result."
function StrSplitAcc(s: string, cur: string): seq<string>
{
  if |s| == 0 then (if |cur| == 0 then [] else [cur])
  else if IsPyWhitespace(s[0]) then
    (if |cur| == 0 then StrSplitAcc(s[1..], "") else [cur] + StrSplitAcc(s[1..], ""))
  else StrSplitAcc(s[1..], cur + [s[0]])
}

// str.split(): "Return a list of the substrings in the string ... will split on
// any whitespace character ... and will discard empty strings from the result."
function StrSplit(s: string): seq<string>
{
  StrSplitAcc(s, "")
}

// sorted helper: insert x into the ascending sequence s.
function SortedInsert(x: int, s: seq<int>): seq<int>
{
  if |s| == 0 then [x]
  else if x <= s[0] then [x] + s
  else [s[0]] + SortedInsert(x, s[1..])
}

// sorted: "Return a new list containing all items from the iterable in ascending order."
function PySorted(s: seq<int>): seq<int>
{
  if |s| == 0 then [] else SortedInsert(s[0], PySorted(s[1..]))
}

// str.join: "Concatenate any number of strings. The string whose method is
// called is inserted in between each given string."
// "Example: '.'.join(['ab', 'pq', 'rs']) -> 'ab.pq.rs'"
function StrJoin(sep: string, parts: seq<string>): string
{
  if |parts| == 0 then ""
  else if |parts| == 1 then parts[0]
  else parts[0] + sep + StrJoin(sep, parts[1..])
}

// dict.items: "Return a set-like object providing a view on the dict's items."
// Under the shared convention, dict -> map, so insertion order is not modeled.
function DictItems<K, V>(m: map<K, V>): set<(K, V)>
{
  set k | k in m.Keys :: (k, m[k])
}
```

