// Library theory for: set(...), list(...), list.sort()

// "If no argument is given ... None" / list.sort: "Sort the list in ascending order and return None."
datatype Option<T> = None | Some(value: T)

// set: "Build an unordered collection of unique elements."
// set(l) contains exactly the elements occurring in the iterable l.
function PySet(l: seq<int>): set<int>
{
  set x | x in l
}

// list: "Built-in mutable sequence. ... The argument must be an iterable if specified."
// list(s) for a set s: a sequence listing each element of the (unordered) set exactly once;
// the iteration order of a set is unspecified, so this is a relation, not a function.
predicate ListFromSet(s: set<int>, r: seq<int>)
{
  (forall i, j :: 0 <= i < j < |r| ==> r[i] != r[j]) &&
  (forall x :: x in r <==> x in s)
}

// list.sort: "Sort the list in ascending order"
predicate IsSortedAscending(r: seq<int>)
{
  forall i, j :: 0 <= i < j < |r| ==> r[i] <= r[j]
}

// list.sort: "The sort is in-place (i.e. the list itself is modified)"
// After the call, the list holds a permutation of its original contents, in ascending order.
predicate ListSortEffect(before: seq<int>, after: seq<int>)
{
  multiset(after) == multiset(before) && IsSortedAscending(after)
}

// list.sort: "... and return None."
// The value of the expression `xs.sort()` is always None.
function ListSortReturn<T>(before: seq<int>): Option<T>
{
  None
}
