  decreases stop - start
{
  if start >= stop then [] else [start] + PyRange(start + 1, stop)
}

// "Return an object that produces a sequence of integers from start (inclusive)
//  to stop (exclusive) by step. ... When step is given, it specifies the increment (or decrement)."
// For step > 0: start, start+step, ... while < stop.
// For step < 0: start, start+step, ... while > stop.
// (step == 0 raises ValueError in Python; excluded by precondition.)
function PyRangeStep(start: int, stop: int, step: int): seq<int>
  requires step != 0
  decreases if step > 0 then stop - start else start - stop
