// Python built-in theory for: str.split, str.isnumeric, int(str), `in` on strings.
// len / range / indexing map directly to Dafny |s|, ranges, and s[i].

// "will split on any whitespace character (including \n \r \t \f and spaces)"
// Modeling assumption: ASCII whitespace as recognized by Python str.isspace
// (space, \t, \n, \v, \f, \r, \x1c-\x1f); non-ASCII Unicode whitespace is ignored.
predicate IsWhitespace(c: char)
{
  c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\x0b' || c == '\x0c'
  || ('\x1c' <= c && c <= '\x1f')
}

// Helper for str.split(): the maximal leading run of non-whitespace characters.
function LeadingWord(s: string): string
  ensures |LeadingWord(s)| <= |s|
  ensures LeadingWord(s) == s[..|LeadingWord(s)|]
  ensures |s| > 0 && !IsWhitespace(s[0]) ==> |LeadingWord(s)| >= 1
  ensures forall c :: c in LeadingWord(s) ==> !IsWhitespace(c)
  ensures |LeadingWord(s)| < |s| ==> IsWhitespace(s[|LeadingWord(s)|])
  decreases |s|
{
  if |s| == 0 || IsWhitespace(s[0]) then ""
  else [s[0]] + LeadingWord(s[1..])
}

// str.split() with sep=None, maxsplit=-1:
// "Return a list of the substrings in the string ... When set to None (the default value),
//  will split on any whitespace character ... and will discard empty strings from the result."
// "Splitting starts at the front of the string and works to the end."
function StrSplit(s: string): seq<string>
  decreases |s|
{
  if |s| == 0 then []
  else if IsWhitespace(s[0]) then StrSplit(s[1..])
  else
    var w := LeadingWord(s);
    [w] + StrSplit(s[|w|..])
}

// Modeling assumption: "numeric" characters restricted to ASCII decimal digits '0'..'9'
// (Python also accepts other Unicode numeric characters such as '²' or '½').
predicate IsNumericChar(c: char)
{
  '0' <= c && c <= '9'
}

// str.isnumeric: "A string is numeric if all characters in the string are numeric and
// there is at least one character in the string."
predicate StrIsNumeric(s: string)
{
  |s| >= 1 && forall i :: 0 <= i < |s| ==> IsNumericChar(s[i])
}

// Helper: value of a decimal digit character.
function DigitValue(c: char): int
  requires IsNumericChar(c)
{
  (c as int) - ('0' as int)
}

// Helper: base-10 value of a string of decimal digits (most significant digit first).
function DecimalValue(s: string): int
  requires forall i :: 0 <= i < |s| ==> IsNumericChar(s[i])
  decreases |s|
{
  if |s| == 0 then 0
  else DecimalValue(s[..|s|-1]) * 10 + DigitValue(s[|s|-1])
}

// int(x) for a string x: "x must be a string ... representing an integer literal in the
// given base. ... The base defaults to 10."
// Restricted to strings that are numeric per StrIsNumeric (ASCII digits, no sign/whitespace).
function PyIntOfStr(s: string): int
