// enumerate: "The enumerate object yields pairs containing a count (from start, which
// defaults to zero) and a value yielded by the iterable argument."
// "(0, seq[0]), (1, seq[1]), (2, seq[2]), ..."
function Enumerate<T>(s: seq<T>): seq<(int, T)>
{
  seq(|s|, i requires 0 <= i < |s| => (i, s[i]))
}

// list.append: "Append object to the end of the list."
function ListAppend<T>(s: seq<T>, x: T): seq<T>
{
  s + [x]
}

// Python tuple comparison (lexicographic) used by sorted on (int, int) tuples:
// "Tuples are compared lexicographically using comparison of corresponding elements."
predicate TupleLt(a: (int, int), b: (int, int))
{
  a.0 < b.0 || (a.0 == b.0 && a.1 < b.1)
}

// Helper for stable ascending insertion: x goes before the first element strictly greater.
function InsertAscPair(x: (int, int), s: seq<(int, int)>): seq<(int, int)>
  decreases |s|
{
  if |s| == 0 then [x]
  else if TupleLt(x, s[0]) then [x] + s
  else [s[0]] + InsertAscPair(x, s[1..])
}

// sorted: "Return a new list containing all items from the iterable in ascending order."
// (specialised to lists of (int, int) tuples; Python's sort is stable)
function SortedPairs(s: seq<(int, int)>): seq<(int, int)>
  decreases |s|
{
  if |s| == 0 then []
  else InsertAscPair(s[|s| - 1], SortedPairs(s[..|s| - 1]))
}

// Helper for stable descending insertion by key: x goes before the first element
// whose key is strictly smaller; equal keys keep original order (stability).
function InsertDescByKey<T>(x: T, s: seq<T>, key: T -> int): seq<T>
  decreases |s|
{
  if |s| == 0 then [x]
  else if key(x) > key(s[0]) then [x] + s
  else [s[0]] + InsertDescByKey(x, s[1..], key)
}

// sorted(iterable, key=key, reverse=True):
// "A custom key function can be supplied to customize the sort order, and the
// reverse flag can be set to request the result in descending order."
// (Python's sort is stable, also with reverse=True: equal-key items keep original order.)
function SortedByKeyReverse<T>(s: seq<T>, key: T -> int): seq<T>
  decreases |s|
{
  if |s| == 0 then []
  else InsertDescByKey(s[|s| - 1], SortedByKeyReverse(s[..|s| - 1], key), key)
