// list(iterable) builds a new list holding the same items in the same order (a shallow copy).
function ListCopy<T>(s: seq<T>): seq<T> {
  s
}

// Subscription s[i] with a possibly negative index: a negative index i means len(s) + i.
function PyIndex(s: seq<int>, i: int): int
  requires 0 - Len(s) <= i && i < Len(s) {
  if i < 0 then s[Len(s) + i] else s[i]
}

// Python `%`: the result has the sign of the divisor (floor semantics), and
// a == (a // b) * b + a % b.
function PyMod(a: int, b: int): int
  requires b != 0 {
  if b < 0 && a % b != 0 then a % b + b else a % b
}

// list.append: "Append object to the end of the list."
function ListAppend<T>(s: seq<T>, x: T): seq<T> {
  s + [x]
}

// Helper for list.sort: insert x into an ascending sorted sequence.
function InsertAsc(x: int, s: seq<int>): seq<int> {
  if |s| == 0 then [x]
  else if x <= s[0] then [x] + s
  else [s[0]] + InsertAsc(x, s[1..])
}

// Helper for list.sort(reverse=True): insert x into a descending sorted sequence.
function InsertDesc(x: int, s: seq<int>): seq<int> {
  if |s| == 0 then [x]
  else if x >= s[0] then [x] + s
  else [s[0]] + InsertDesc(x, s[1..])
}

// list.sort: "Sort the list in ascending order and return None."
// "The reverse flag can be set to sort in descending order."
// (Stability is unobservable for plain ints, since equal ints are indistinguishable.)
// The result is the contents of the list after the in-place sort.
function ListSort(s: seq<int>, reverse: bool): seq<int> {
  if |s| == 0 then []
  else if reverse then InsertDesc(s[0], ListSort(s[1..], reverse))
  else InsertAsc(s[0], ListSort(s[1..], reverse))
}

// "Sort the list in ascending order": every earlier element is <= every later one.
predicate IsSortedAsc(s: seq<int>) {
  forall i, j :: 0 <= i < j < |s| ==> s[i] <= s[j]
}

// "The reverse flag can be set to sort in descending order."
predicate IsSortedDesc(s: seq<int>) {
  forall i, j :: 0 <= i < j < |s| ==> s[i] >= s[j]
}

// "The sort is in-place (i.e. the list itself is modified)": same items, rearranged.
predicate IsPermutation(a: seq<int>, b: seq<int>) {
  multiset(a) == multiset(b)
