// "all cased characters in the string are uppercase" -- per-character uppercase property; exact on ASCII.
function {:axiom} CharIsUpper(c: char): bool
  ensures (c as int) < 128 ==> (CharIsUpper(c) <==> 'A' <= c <= 'Z')

// "Return a copy of the string converted to lowercase." -- per-character lowercase mapping
// (may yield several chars in Unicode); exact on ASCII.
function {:axiom} CharLower(c: char): string
  ensures 'A' <= c <= 'Z' ==> CharLower(c) == [((c as int) + 32) as char]
  ensures (c as int) < 128 && !('A' <= c <= 'Z') ==> CharLower(c) == [c]

// "Return a copy of the string converted to uppercase." -- per-character uppercase mapping
// (may yield several chars in Unicode, e.g. 'ß' -> "SS"); exact on ASCII.
