  ensures 'a' <= c <= 'z' ==> CharUpper(c) == [((c as int) - 32) as char]
  ensures (c as int) < 128 && !('a' <= c <= 'z') ==> CharUpper(c) == [c]

// ---------------- str methods ----------------

